INSERT INTO intake_events (session_id,seq,kind,source,label,payload_json,created_at) VALUES (1,1,'transcript_chunk','user','','{"text": "So the thing customers keep asking for is saved filters in the portal.", "spoken": true}',datetime('now','-14 minutes'));
INSERT INTO intake_events (session_id,seq,kind,source,label,payload_json,created_at) VALUES (1,2,'transcript_chunk','user','','{"text": "Right now every time they come back they re-pick the same project and the same status filter, every single visit.", "spoken": true}',datetime('now','-13 minutes'));
INSERT INTO intake_events (session_id,seq,kind,source,label,payload_json,created_at) VALUES (1,3,'transcript_chunk','user','','{"text": "I want them to be able to name a filter and pin it, and have it still be there next week.", "spoken": true}',datetime('now','-12 minutes'));
INSERT INTO intake_events (session_id,seq,kind,source,label,payload_json,created_at) VALUES (1,4,'transcript_chunk','user','','{"text": "It should be per user, not per company \u2014 two people at the same customer will care about different things.", "spoken": true}',datetime('now','-11 minutes'));
INSERT INTO intake_events (session_id,seq,kind,source,label,payload_json,created_at) VALUES (1,5,'project_match','ai','','{"matches": [{"project_id": 2, "key": "ACME", "name": "Acme GmbH", "score": 94, "confidence": "high", "rationale": "Customer portal, saved filters and per-user preferences all map to the Acme retainer scope."}, {"project_id": 1, "key": "PAI", "name": "PAIMOS", "score": 41, "confidence": "low", "rationale": "Portal code lives here, but the request is customer-scoped."}], "threshold": 90, "detected_project_id": 2, "detected_score": 94}',datetime('now','-10 minutes'));
INSERT INTO intake_events (session_id,seq,kind,source,label,payload_json,created_at) VALUES (1,6,'spec','ai','','{"markdown": "# Saved filters in the customer portal\n\n## Summary\nPortal users can name, pin and reuse a filter combination. A saved filter\nbelongs to one person, not to the customer account, and survives sign-out.\n\n## Problem\nEvery portal visit starts from a blank slate: project, then status, then\ndate range \u2014 the same three choices, re-made each time. For a weekly\ncheck-in that is the entire interaction, repeated. Two people at the same\ncustomer routinely want different views, so a shared default would not\nhelp either of them.\n\n## Proposed solution\n- A **Save filter** control in the portal filter bar, capturing the active\n  project / status / date-range combination under a user-supplied name.\n- Saved filters are listed in the portal sidebar, newest first, and pinned\n  ones surface above the rest.\n- Scope is **per portal user**. Nothing a customer saves is visible to\n  their colleagues.\n- Applying a saved filter is a single click and updates the URL, so the\n  view stays shareable and bookmarkable.\n\n## Open points\n- Whether a customer admin may publish one filter as a team default (out\n  of scope for a first cut; the data model should not preclude it).\n- Retention when a project is archived \u2014 hide the filter, or keep it and\n  show an empty result?\n\n## Acceptance criteria\n- [ ] A portal user can save the active filter under a name.\n- [ ] Saved filters persist across sessions and devices.\n- [ ] Filters are private to the user who created them.\n- [ ] Pinned filters appear above unpinned ones.\n- [ ] Applying a filter updates the URL and the result set together.", "language": "en", "finish": "stop"}',datetime('now','-9 minutes'));
INSERT INTO intake_events (session_id,seq,kind,source,label,payload_json,created_at) VALUES (1,7,'ticket_preview','ai','','{"title": "Saved filters in the customer portal", "issue_type": "ticket", "description": "Let a portal user name, pin and reuse a filter combination (project, status, date range). Saved filters are private to the individual user, persist across sessions and devices, and applying one updates the URL so the view stays shareable.", "acceptance_criteria": "- [ ] Save the active filter under a name\n- [ ] Persists across sessions and devices\n- [ ] Private to the creating user\n- [ ] Pinned filters sort above unpinned\n- [ ] Applying updates URL and results together", "language": "en"}',datetime('now','-8 minutes'));
INSERT INTO intake_events (session_id,seq,kind,source,label,payload_json,created_at) VALUES (1,8,'impacts','ai','','{"impacted": [{"issue_key": "ACME-35", "title": "Portal: saved filters per customer", "category": "conflicts", "via": "retrieval", "mapped_relation": "related"}, {"issue_key": "ACME-12", "title": "Customer portal shell + navigation", "category": "touches", "via": "graph"}, {"issue_key": "ACME-19", "title": "Portal issue list filtering", "category": "extends", "via": "retrieval"}], "related": [{"issue_key": "ACME-40", "title": "Portal login should honour SSO domains", "category": "related", "via": "retrieval"}], "graph_hits": [{"entity_type": "file", "title": "frontend/src/views/portal/PortalIssues.vue"}, {"entity_type": "file", "title": "backend/handlers/portal.go"}]}',datetime('now','-7 minutes'));
INSERT INTO intake_events (session_id,seq,kind,source,label,payload_json,created_at) VALUES (1,9,'summaries','ai','','{"eli5": "People who log in to see their project keep picking the same things every time. This lets them save that choice and give it a name, so next time it is one click.", "eli10": "Portal users repeat the same project + status + date choices on every visit. The change adds named, saved filter combinations that belong to the individual user and persist across sessions. Pinned ones appear first, and applying one updates the URL so the view can still be shared.", "eli15": "Adds per-user persisted filter presets to the customer portal. The active project/status/date-range combination can be saved under a user-supplied name, listed newest-first with pinned entries promoted, and applied in one click with the URL kept in sync so views remain shareable and bookmarkable. Scope is deliberately per portal user rather than per customer account, because colleagues at the same customer track different things; a published team default is acknowledged as a possible later extension and the data model should not preclude it. Open: retention behaviour when a project is archived.", "language": "en"}',datetime('now','-6 minutes'));
